import "server-only";
import { cache } from "react";
import { getServiceClient } from "./supabase-service";
import { analyzeArticleRelevance } from "./relevance";
import { articleUrlVariants } from "./url";
import { looksLikeJunkContent } from "./content-quality";
import { cleanArticleContent } from "./article-clean";
import type { ArticleContent, NewsArticle } from "./types";

const ARTICLE_COLUMNS =
  "url, title, snippet, thumbnail, source, language, category, relevance, published_at, fetched_at, author, hero_image, word_count, tags, title_vi, snippet_vi";

/**
 * Rows that are not written articles and must not appear in the news feed.
 *
 * `lfctv` is the club's YouTube output. It lives in the same table because it
 * has the same shape — title, url, thumbnail, date, source — and gets dedup,
 * thumbnails, retention and cleanup for free, but a video is not a story and
 * would otherwise take a slot from one. The /news page shows these in their own
 * strip; `getVideoItemsFromDB` is the only reader that wants them.
 */
export const NON_ARTICLE_SOURCES = ["lfctv"] as const;
const NON_ARTICLE_FILTER = `(${NON_ARTICLE_SOURCES.join(",")})`;

const FRESH_CONTENT_TTL_MS = 7 * 24 * 3600 * 1000; // 7 days
const PREFERRED_LANGUAGE_SHARE = 0.8; // Vietnamese locale should read VI-first, not 50/50.

// DB row → NewsArticle mapping
interface ArticleRow {
  url: string;
  title: string;
  snippet: string;
  thumbnail: string | null;
  source: string;
  language: string;
  category: string;
  relevance: number;
  published_at: string | null;
  fetched_at: string | null;
  author: string | null;
  hero_image: string | null;
  word_count: number | null;
  tags: string[] | null;
  title_vi: string | null;
  snippet_vi: string | null;
}

function rowToArticle(row: ArticleRow): NewsArticle {
  return {
    title: row.title,
    link: row.url,
    pubDate: row.published_at ?? row.fetched_at ?? "",
    contentSnippet: row.snippet,
    thumbnail: row.thumbnail ?? row.hero_image ?? undefined,
    source: row.source as NewsArticle["source"],
    language: row.language as NewsArticle["language"],
    category: (row.category as NewsArticle["category"]) ?? "general",
    relevanceScore: row.relevance,
    author: row.author ?? undefined,
    heroImage: row.hero_image ?? undefined,
    wordCount: row.word_count ?? undefined,
    tags: row.tags ?? undefined,
  };
}

function onlyRelevantArticles(rows: ArticleRow[]): NewsArticle[] {
  return rows
    .map(rowToArticle)
    .filter((article) => analyzeArticleRelevance(article).isRelevant);
}

/**
 * Fetch news from DB only.
 *
 * Important: this function must never crawl or sync. News ingestion is owned by
 * the external crawler / explicit cron, so user-facing pages stay side-effect free.
 */
/**
 * For `unstable_cache` wrappers: getNewsFromDB swallows database errors and
 * returns [], and caching that [] blanked the news on `/` and `/news` for the
 * whole revalidate window after any blip (seen right after the database was
 * resumed). Throwing on an empty result keeps it out of the cache; callers
 * `.catch(() => [])`. A genuinely empty feed is just re-queried, which is cheap.
 */
export async function requireNonEmptyNews(articles: Promise<NewsArticle[]>): Promise<NewsArticle[]> {
  const list = await articles;
  if (list.length === 0) throw new Error("[news/db] no articles (database error or empty) — not caching");
  return list;
}

/**
 * The newest video rows — the mirror of the exclusion above.
 *
 * No relevance filter: every upload on the club's own channel is about the club
 * by definition, and `analyzeArticleRelevance` scores written prose, so a
 * one-line video description scores far too low to survive it.
 */
export const getVideoItemsFromDB = cache(async (limit = 6): Promise<NewsArticle[]> => {
  try {
    const { data, error } = await getServiceClient()
      .from("articles")
      .select(ARTICLE_COLUMNS)
      .eq("is_active", true)
      .not("published_at", "is", null)
      .in("source", [...NON_ARTICLE_SOURCES])
      .order("published_at", { ascending: false, nullsFirst: false })
      .limit(limit);

    if (error) {
      console.error("[news/db] video items:", error.message);
      return [];
    }
    return ((data ?? []) as ArticleRow[]).map(rowToArticle);
  } catch (err) {
    console.error("[news/db] video items failed:", err);
    return [];
  }
});

export const getNewsFromDB = cache(
  async (
    limit = 30,
    preferLang?: string,
    _options?: { skipSync?: boolean }
  ): Promise<NewsArticle[]> => {
    void _options;
    try {
      // Use service client for public article reads (no auth needed, avoids cookie issues in ISR)
      const supabase = getServiceClient();

      // One query, newest first, then relevance. There used to be two: a quota
      // split between the preferred language and the rest (80/20), plus a
      // balanced EN/VI pair when no language was preferred. Both broke the day
      // the Vietnamese feeds were dropped — with one language in the corpus the
      // other side of every quota came back empty and was never topped up, so
      // `limit` 12 returned 2 on the home page and half of `limit` everywhere
      // else. Ordering by date first is language-neutral anyway, which is what
      // the quota was there to protect: the original concern was a *relevance*
      // sort burying one language, and relevance is only the tie-break here.
      const { data, error } = await supabase
        .from("articles")
        .select(ARTICLE_COLUMNS)
        .eq("is_active", true)
        .not("published_at", "is", null)
        .not("source", "in", NON_ARTICLE_FILTER)
        .order("published_at", { ascending: false, nullsFirst: false })
        .order("relevance", { ascending: false, nullsFirst: false })
        .limit(limit);

      if (error) console.error("[news/db] error:", error.message);
      const articles = onlyRelevantArticles((data ?? []) as ArticleRow[]);
      if (!preferLang) return articles;

      // A preference, not a quota: the reader's language first, each group
      // keeping its own order, and nothing dropped when a language is absent.
      return [
        ...articles.filter((a) => a.language === preferLang),
        ...articles.filter((a) => a.language !== preferLang),
      ];
    } catch (err) {
      console.error("[news/db] Fatal:", err);
      return [];
    }
  }
);

/** One stored article (title, snippet, images) by URL, for pages whose body can't be shown. */
export const getArticleByUrl = cache(async (url: string): Promise<NewsArticle | null> => {
  try {
    const supabase = getServiceClient();
    const { data } = await supabase
      .from("articles")
      .select(ARTICLE_COLUMNS)
      .in("url", articleUrlVariants(url))
      .limit(1)
      .maybeSingle();
    return data ? rowToArticle(data as ArticleRow) : null;
  } catch {
    return null;
  }
});

export const getArticleContentFromDB = cache(
  async (url: string): Promise<ArticleContent | null> => {
    try {
      const supabase = getServiceClient();
      const { data } = await supabase
        .from("articles")
        .select("content_en, content_scraped_at")
        .in("url", articleUrlVariants(url))
        .order("content_scraped_at", { ascending: false, nullsFirst: false })
        .limit(1)
        .maybeSingle();

      if (!data?.content_en || !data.content_scraped_at) {
        return null;
      }

      const ageMs = Date.now() - new Date(data.content_scraped_at).getTime();
      if (ageMs > FRESH_CONTENT_TTL_MS) {
        return null;
      }

      const content = data.content_en as ArticleContent;
      return looksLikeJunkContent(content) ? null : cleanArticleContent(content);
    } catch {
      return null;
    }
  }
);

/**
 * Search articles using full-text search.
 */
export const searchArticles = cache(
  async (query: string, limit = 20): Promise<NewsArticle[]> => {
    try {
      const supabase = getServiceClient();
      const tsQuery = query.trim().split(/\s+/).join(" & ");

      const { data, error } = await supabase
        .from("articles")
        .select(ARTICLE_COLUMNS)
        .eq("is_active", true)
        .textSearch("fts", tsQuery)
        .order("relevance", { ascending: false })
        .limit(limit);

      if (error) {
        console.error("[news/db] Search error:", error.message);
        return [];
      }

      return onlyRelevantArticles((data ?? []) as ArticleRow[]);
    } catch (err) {
      console.error("[news/db] Search fatal:", err);
      return [];
    }
  }
);

/**
 * Newest articles whose headline names a player ("Isak", "Araújo"), for the
 * player page. Matches the surname with and without accents, since outlets
 * spell "Araujo" both ways. Errors return [] (the section then hides).
 */
export const getArticlesMentioning = cache(
  async (name: string, limit = 6): Promise<NewsArticle[]> => {
    const plain = name.normalize("NFD").replace(/\p{M}/gu, "");
    // PostgREST `or` syntax: commas and parentheses would split the filter.
    const safe = (s: string) => s.replace(/[,()%*]/g, "");
    const terms = [...new Set([safe(name), safe(plain)])].filter((t) => t.length >= 3);
    if (terms.length === 0) return [];
    try {
      const { data, error } = await getServiceClient()
        .from("articles")
        .select(ARTICLE_COLUMNS)
        .eq("is_active", true)
        .or(terms.map((t) => `title.ilike.*${t}*`).join(","))
        .order("published_at", { ascending: false })
        .limit(limit * 2);
      if (error) {
        console.error("[news/db] Mentions error:", error.message);
        return [];
      }
      return onlyRelevantArticles((data ?? []) as ArticleRow[]).slice(0, limit);
    } catch (err) {
      console.error("[news/db] Mentions fatal:", err);
      return [];
    }
  }
);

/**
 * Paginated article query for load-more. No sync trigger.
 */
export async function getNewsPaginated(
  offset: number,
  limit: number,
  language?: "en" | "vi"
): Promise<{ articles: NewsArticle[]; hasMore: boolean }> {
  try {
    const supabase = getServiceClient();

    let query = supabase
      .from("articles")
      .select(ARTICLE_COLUMNS)
      .eq("is_active", true)
      // Keep page 2 consistent with page 1, which getNewsFromDB filters.
      .not("source", "in", NON_ARTICLE_FILTER)
      // Postgres sorts NULL first on DESC: undated rows must come LAST, not top the list.
      .order("published_at", { ascending: false, nullsFirst: false })
      .range(offset, offset + limit); // fetch limit+1 to check hasMore

    if (language) query = query.eq("language", language);

    const { data, error } = await query;
    if (error) {
      console.error("[news/db] Paginate error:", error.message);
      return { articles: [], hasMore: false };
    }

    const rows = (data ?? []) as ArticleRow[];
    const hasMore = rows.length > limit;
    const articles = onlyRelevantArticles(hasMore ? rows.slice(0, limit) : rows);
    return { articles, hasMore };
  } catch (err) {
    console.error("[news/db] Paginate fatal:", err);
    return { articles: [], hasMore: false };
  }
}

export interface ArticleRef {
  title: string;
  /** Feed thumbnail, else the scraped hero image; null when neither is known. */
  image: string | null;
}

/**
 * Title and picture for a set of article URLs (the digest page shows them as
 * its source links and story images).
 */
export async function getArticleRefsByUrls(
  urls: string[]
): Promise<Record<string, ArticleRef>> {
  if (!urls.length) return {};
  try {
    const supabase = getServiceClient();
    // Rows may be stored in a legacy spelling (trailing slash, feed tracking
    // params); answer under the URL the caller asked about.
    const requestedByVariant = new Map<string, string>();
    for (const requested of urls) {
      for (const variant of articleUrlVariants(requested)) {
        if (!requestedByVariant.has(variant)) requestedByVariant.set(variant, requested);
      }
    }
    const { data } = await supabase
      .from("articles")
      .select("url, title, thumbnail, hero_image")
      .in("url", [...requestedByVariant.keys()]);
    const map: Record<string, ArticleRef> = {};
    for (const row of data ?? []) {
      map[requestedByVariant.get(row.url) ?? row.url] = {
        title: row.title,
        image: row.thumbnail || row.hero_image || null,
      };
    }
    return map;
  } catch {
    return {};
  }
}

/** Lightweight query for sitemap: active article URLs + publish dates (last 90 days) */
export async function getArticleSitemapData(): Promise<{ url: string; published_at: string }[]> {
  try {
    const supabase = getServiceClient();
    const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString();
    const { data } = await supabase
      .from("articles")
      .select("url, published_at")
      .gte("published_at", cutoff)
      .eq("is_active", true)
      // These rows link out to youtube.com; our sitemap lists our own pages.
      .not("source", "in", NON_ARTICLE_FILTER)
      .order("published_at", { ascending: false })
      .limit(500);
    return (data ?? []).filter((r) => r.url && r.published_at);
  } catch {
    return [];
  }
}
